from __future__ import annotations

import base64
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
FILES = {'.github/workflows/publish.yml': '',
 'README.md': '',
 'cloudflare-scheduler/wrangler.toml': '',
 'config/scoring_candidate.json': '',
 'dashboard/ai_analysis.py': '',
 'dashboard/builder.py': '',
 'dashboard/narrative.py': '',
 'dashboard/schedule.py': '',
 'dashboard/scoring.py': '',
 'scripts/should_refresh.py': '',
 'site/assets/app.css': '',
 'site/assets/app.js': '',
 'site/index.html': '',
 'tests/test_preopen.py': '',
 'tests/test_schedule.py': '',
 'tests/test_scoring.py': ''}

for relative, encoded in FILES.items():
    target = ROOT / relative
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(base64.b64decode(encoded))

Path(__file__).unlink()
print(f"Applied {len(FILES)} release files")
